 const [chatHistory,setChatHistory]=useState<{ids:string[];ownerId:string}|null>(null);
 const hasComposerInput=active?.isBot&&s.hasChatLockCode?draft.length>0:!!draft.trim();
 const savedComposition=useRef<{text:string;reply:ChatMessage|null;file:File|null;userId:string;peerId:string}|null>(null);
 const composerCursor=useRef({start:0,end:0,text:'',userId:'',peerId:'',revision:0});
 const selectedMessages=messages.filter(message=>selectedIds.includes(message.id)&&!message.system);
 const actionMessages=messageAction&&messageAction.userId===s.user?.id&&messageAction.peerId===s.activeId?messages.filter(message=>messageAction.ids.includes(message.id)&&!message.system):[];
 const forwardingContacts=s.conversations.filter(contact=>!contact.hidden&&(!contact.locked||s.lockedChatsOpen)&&!contact.isBot&&!contact.isGroup&&!contact.blocked&&!contact.keyChanged&&contact.requestStatus!=='outgoing');
 const canDeleteEveryone=actionMessages.length>0&&actionMessages.every(message=>message.own&&!message.deleted&&!message.isBot&&!active?.isBot&&!active?.isGroup&&!['queued','sending','failed'].includes(message.status)&&(s.mode==='demo'||!!message.serverId));
 const deleteStates=canDeleteEveryone?actionMessages.map(message=>getMessageDeletionState(message,Math.max(deletionClock,Date.now()))):[];
 const blockedDeleteState=deleteStates.find(state=>!state.allowed);
 const deleteEveryoneDisabledReason=blockedDeleteState?(blockedDeleteState.reason||'Delete for everyone is unavailable for this selection.'):undefined;
 const deleteDeadlines=[...deleteStates.map(state=>state.expiresAt),...actionMessages.map(message=>message.expiresAt)].filter((at):at is number=>at!==undefined);
 const deleteEveryoneExpiresAt=deleteDeadlines.length?Math.min(...deleteDeadlines):undefined;
 useEffect(()=>{setAiStatus(null);if(!s.user||s.mode!=='live'||!active?.isBot)return;const ownerId=s.user.id,controller=new AbortController();let alive=true;async function refresh(){if(document.visibilityState!=='visible')return;try{const value=await api<AiStatus>('/api/bot/status',{signal:controller.signal});if(alive&&useVeilnivo.getState().user?.id===ownerId&&['ollama','openai-compatible','none'].includes(value.provider)&&typeof value.configured==='boolean'&&typeof value.connected==='boolean')setAiStatus(value)}catch{}}void refresh();const timer=setInterval(()=>void refresh(),15000);return()=>{alive=false;controller.abort();clearInterval(timer)}},[s.user?.id,s.mode,active?.isBot]);
 useEffect(()=>{if(messageAction?.kind!=='delete'||!actionMessages.length)return;setDeletionClock(Date.now());const timer=setInterval(()=>setDeletionClock(Date.now()),1000);return()=>clearInterval(timer)},[messageAction?.kind,messageAction?.userId,messageAction?.peerId,actionMessages.length]);
 useEffect(()=>{setSelectedIds([]);setMessageAction(null);setEditing(null);savedComposition.current=null;setChatHistory(null);draftRef.current='';setDraft('');setReply(null);setFile(null);setEmoji(false);setChatSearch(false);setMessageQuery('');setInfo(false);setMenu(false);composerCursor.current={start:0,end:0,text:'',userId:'',peerId:'',revision:composerCursor.current.revision+1}},[s.user?.id,s.activeId]);
 useEffect(()=>{setSelectedIds(previous=>{const kept=previous.filter(id=>messages.some(message=>message.id===id));return kept.length===previous.length?previous:kept});if(editing&&!messages.some(message=>message.id===editing.id&&!message.deleted))cancelEdit();if(reply){const latest=messages.find(message=>message.id===reply.id&&!message.deleted);if(!latest)setReply(null);else if(latest!==reply)setReply(latest)}},[messages,editing?.id,reply?.id]);
 function rememberCursor(){const area=textarea.current;if(area&&area.value===draftRef.current)composerCursor.current={start:(area.selectionStart??draftRef.current.length),end:(area.selectionEnd??draftRef.current.length),text:draftRef.current,userId:s.user?.id??'',peerId:s.activeId,revision:composerCursor.current.revision+1}}
 function currentCursor(){const cursor=composerCursor.current;if(cursor.userId===s.user?.id&&cursor.peerId===s.activeId&&cursor.text===draftRef.current)return cursor;const area=textarea.current;return{...cursor,start:area?.value===draftRef.current?(area.selectionStart??draftRef.current.length):draftRef.current.length,end:area?.value===draftRef.current?(area.selectionEnd??draftRef.current.length):draftRef.current.length}}
 function placeCaret(start:number,end=start){
  const userId=s.user?.id??'',peerId=s.activeId,revision=composerCursor.current.revision+1;
  composerCursor.current={start,end,text:draftRef.current,userId,peerId,revision};
  requestAnimationFrame(()=>{const current=useVeilnivo.getState();if(composerCursor.current.revision!==revision||current.user?.id!==userId||current.activeId!==peerId||!textarea.current)return;textarea.current.focus({preventScroll:true});textarea.current.setSelectionRange(start,end);textarea.current.style.height='26px';textarea.current.style.height=Math.min(textarea.current.scrollHeight,130)+'px'});
 }
 function cancelEdit(){const saved=savedComposition.current;savedComposition.current=null;setEditing(null);const current=useVeilnivo.getState();if(saved&&current.user?.id===saved.userId&&current.activeId===saved.peerId){draftRef.current=saved.text;setDraft(saved.text);setReply(saved.reply);setFile(saved.file);placeCaret(saved.text.length)}}
 function beginEdit(message:ChatMessage){
  const current=useVeilnivo.getState();if(!s.user||current.user?.id!==s.user.id||current.activeId!==s.activeId||!message.own||message.deleted||active?.isBot||active?.isGroup)return;
  if(!editing)savedComposition.current={text:draftRef.current,reply,file,userId:s.user.id,peerId:s.activeId};
  setEditing(message);setReply(null);setFile(null);setEmoji(false);setSelectedIds([]);s.clearError();draftRef.current=message.text;setDraft(message.text);placeCaret(message.text.length);
 }
 function beginReply(message:ChatMessage){const current=useVeilnivo.getState();if(message.deleted||current.user?.id!==s.user?.id||current.activeId!==s.activeId)return;if(editing)cancelEdit();setReply(message);setEmoji(false);const userId=s.user?.id,peerId=s.activeId;requestAnimationFrame(()=>{const latest=useVeilnivo.getState();if(latest.user?.id===userId&&latest.activeId===peerId)textarea.current?.focus({preventScroll:true})})}
 function toggleSelected(id:string){setSelectedIds(previous=>previous.includes(id)?previous.filter(value=>value!==id):previous.length<50?[...previous,id]:previous)}
 function openMessageAction(kind:MessageAction['kind'],ids:string[]){const current=useVeilnivo.getState();if(!s.user||current.user?.id!==s.user.id||current.activeId!==s.activeId)return;typingComposer.current?.stop();setEmoji(false);s.clearError();setMessageAction({kind,ids,userId:s.user.id,peerId:s.activeId})}
 async function finishMessageAction(scope:'me'|'everyone'|string[]){const action=messageAction,current=useVeilnivo.getState();if(!action||current.busy||current.user?.id!==action.userId||current.activeId!==action.peerId)return;const ok=Array.isArray(scope)?await current.forwardMessages(action.ids,scope):await current.deleteMessages(action.ids,scope);const latest=useVeilnivo.getState();if(ok&&latest.user?.id===action.userId&&latest.activeId===action.peerId){setMessageAction(null);setSelectedIds([])}}
 useEffect(()=>{setRecentEmoji([]);setSkinTone(0)},[s.user?.id]);
