  draftRef.current=inserted.text;setDraft(inserted.text);emojiSelection.current={...selection,start:inserted.caret,end:inserted.caret};composerCursor.current={start:inserted.caret,end:inserted.caret,text:inserted.text,userId:selection.userId,peerId:selection.peerId,revision:composerCursor.current.revision+1};
